               if grid[r][c] not in (0, 5) and (r, c) not in borders]

    for y0, y1, x0, x1, frame_color in frames:
        cy, cx = (y0+y1)/2, (x0+x1)/2
        candidates = [p for p in markers if p[2] != frame_color]
        if candidates:
            _, _, fill = min(candidates, key=lambda p: (p[0]-cy)**2 + (p[1]-cx)**2)
        else:
            fill = 0
        for r in range(y0+1, y1):
            for c in range(x0+1, x1):
                if (r+c) % 2 == (y0+x0) % 2:
                    out[r][c] = fill
    return out
